def single_defcom_extract(start_from, srcls, is_class_begin=False):

    i = start_from
    fcombody = ""  # def comment body
    comstart = -1  # the starting line index of comment mark "'''" or """"""
    # if it is not -1, it indicates the loop is in the comment body
    comstyle = 0  # comment mark style ,comments quoted with ''' is coded as 1
    # comments quoted with """ is coded as 2
    for x in range(i + 1, len(srcls)):
        stripped = srcls[x].replace('\t', '    ').strip()
        if is_class_begin and comstart == -1:
            if srcls[x].replace('\t', '    ').startswith('    def '):
                break
        if comstart == -1:
            if stripped.startswith('def ') or stripped.startswith('class '):
                break
            if stripped.startswith('"""'):
                comstart = x
                comstyle = 2
                # single-line docstring: opening and closing on same line
                if len(stripped) > 3 and stripped.endswith('"""'):
                    break
                continue
            if stripped.startswith("'''"):
                comstart = x
                comstyle = 1
                if len(stripped) > 3 and stripped.endswith("'''"):
                    break
                continue
        else:
            if comstyle == 2 and stripped.startswith('"""'):
                break
            if comstyle == 1 and stripped.startswith("'''"):
                break
            fcombody += srcls[x]
    return fcombody

