            relation = 1  # 'left-below'
        return relation
    if vy0 == vy1:
        # 水平线段：uy==vy0 视为 above 侧
        if ux < vx0:
            relation = 0  # 'left-above'
        elif ux == vx0:
            relation = 0  # 'left-above'
