def longestNonWildcardSubsequence(opCodes, mask=None):
    # Invalid values for start and end
    start = 1
    end = 0

    # 空输入保护：opCodes 为空或首元素为空时直接返回
    if not opCodes or not opCodes[0]:
        if mask is None:
            mask = ""
        return start, end, mask

    if mask is None:
        mask = "1" * len(opCodes[0])

    # 校验所有 op 长度与 mask 长度一致，避免后续 op[i] / mask[i] 越界
    for op in opCodes:
        if len(op) != len(mask):
            raise ValueError(
                "opCodes entries and mask must have the same length"
            )

    for x in range(len(mask)):
        for y in range(x, len(mask)):
            rangeGood = True
            for op in opCodes:
                for i in range(x, y + 1):
                    if op[i] == "*" or mask[i] == "*":
                        rangeGood = False
                        break
                if not rangeGood:
                    break
            if rangeGood:
                if y - x > end - start:
                    end = y
                    start = x

    mask = [c for c in mask]

    # 仅当找到有效区间时才标记通配符，避免 start/end 越界
    if end >= start and start >= 0 and end < len(mask):
        for i in range(start, end + 1):
            mask[i] = "*"

    return start, end, "".join(mask)

